const http = require('http');

const payload = JSON.stringify({ message: 'Give me one short career tip', sessionId: 'verify-node' });

const req = http.request(
  {
    hostname: 'localhost',
    port: 5000,
    path: '/chat',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
    },
  },
  (res) => {
    let data = '';
    res.on('data', (chunk) => (data += chunk));
    res.on('end', () => {
      console.log('STATUS:', res.statusCode);
      console.log(data);
    });
  }
);

req.on('error', (err) => {
  console.error('REQUEST_ERROR:', err.message);
});

req.write(payload);
req.end();
